public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();

        int firstQuote = line.indexOf('"');
        int secondQuote = line.indexOf('"', firstQuote + 1);
        String s = line.substring(firstQuote + 1, secondQuote);

        int arrayOpen = line.indexOf('[', secondQuote);
        int arrayClose = line.indexOf(']', arrayOpen);
        String body = line.substring(arrayOpen + 1, arrayClose).trim();

        int[] indices;
        if (body.isEmpty()) {
            indices = new int[0];
        } else {
            String[] parts = body.split(",");
            indices = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                indices[i] = Integer.parseInt(parts[i].trim());
            }
        }

        System.out.println("\"" + new Solution().restoreString(s, indices) + "\"");
    }
}

